update ai_model set is_default=false where provider_id in(select id from ai_provider where kind='LOCAL_DEMO' or name='Aivora 本地演示');
update ai_model set is_default=true where id=(select m.id from ai_model m join ai_provider p on p.id=m.provider_id where m.enabled and p.enabled and p.kind='OPENAI_COMPATIBLE' and p.api_key_ciphertext is not null and p.base_url like 'https://dashscope.aliyuncs.com/%' and m.model_type in ('CHAT','TEXT') order by m.id limit 1) and not exists(select 1 from ai_model m join ai_provider p on p.id=m.provider_id where m.is_default and m.enabled and p.enabled and p.kind='OPENAI_COMPATIBLE' and p.api_key_ciphertext is not null and p.base_url like 'https://dashscope.aliyuncs.com/%' and m.model_type in ('CHAT','TEXT'));
update model_route_rule set model_id=(select m.id from ai_model m join ai_provider p on p.id=m.provider_id where m.enabled and p.enabled and p.kind='OPENAI_COMPATIBLE' and p.api_key_ciphertext is not null and p.base_url like 'https://dashscope.aliyuncs.com/%' and m.model_type in ('CHAT','TEXT') order by m.is_default desc,m.id limit 1) where model_id in(select m.id from ai_model m join ai_provider p on p.id=m.provider_id where p.kind='LOCAL_DEMO' or p.name='Aivora 本地演示') and exists(select 1 from ai_model m join ai_provider p on p.id=m.provider_id where m.enabled and p.enabled and p.kind='OPENAI_COMPATIBLE' and p.api_key_ciphertext is not null and p.base_url like 'https://dashscope.aliyuncs.com/%' and m.model_type in ('CHAT','TEXT'));
update ai_model set enabled=false,is_default=false where provider_id in(select id from ai_provider where kind='LOCAL_DEMO' or name='Aivora 本地演示');
update ai_provider set enabled=false where kind='LOCAL_DEMO' or name='Aivora 本地演示';
